package com.rookhq.monarch.buildlogic.inventory

import java.io.File

/** The content of every generated file. Pure functions of the per-component files. */
object Generators {
    private const val EXAMPLES_PACKAGE = "com.rookhq.monarch.generated.examples"

    /** Packages every example can use without naming them in `imports`. */
    private val defaultImports = listOf(
        "androidx.compose.foundation.*",
        "androidx.compose.foundation.layout.*",
        "androidx.compose.foundation.lazy.*",
        "androidx.compose.foundation.selection.*",
        "androidx.compose.foundation.shape.*",
        "androidx.compose.foundation.text.*",
        "androidx.compose.material3.*",
        "androidx.compose.runtime.*",
        "androidx.compose.runtime.saveable.*",
        "androidx.compose.ui.*",
        "androidx.compose.ui.graphics.*",
        "androidx.compose.ui.graphics.painter.*",
        "androidx.compose.ui.graphics.vector.*",
        "androidx.compose.ui.res.*",
        "androidx.compose.ui.semantics.*",
        "androidx.compose.ui.text.*",
        "androidx.compose.ui.text.font.*",
        "androidx.compose.ui.text.input.*",
        "androidx.compose.ui.text.style.*",
        "androidx.compose.ui.unit.*",
        "com.rookhq.monarch.testing.InventoryExample",
        "com.rookhq.monarch.tokens.*",
    )

    private fun header(source: String) = "// Generated by Gradle from $source. Do not edit.\n"

    /** components.json: every entry, sorted by id. */
    fun componentsJson(entries: List<InventoryEntry>): String = Json.write(entries.sortedBy { it.id }.map { it.raw })

    /**
     * The public packages of monarch-compose, as wildcard imports. `internal`
     * is left out: an example is code an app could write.
     */
    fun monarchImports(layout: MonarchLayout): List<String> =
        kotlinFiles(layout.composeMain)
            .map { it.parentFile.relativeTo(layout.composeMain).invariantSeparatorsPath }
            .distinct()
            .filterNot { it == "internal" || it.startsWith("internal/") }
            .map { path -> if (path.isEmpty()) "com.rookhq.monarch.*" else "com.rookhq.monarch.${path.replace('/', '.')}.*" }
            .sorted()

    /** One Kotlin file per entry that has examples, and an index of all of them. Keys are paths in the output folder. */
    fun exampleFiles(entries: List<InventoryEntry>, monarchImports: List<String>): Map<String, String> {
        val folder = EXAMPLES_PACKAGE.replace('.', '/')
        val withExamples = entries.filter { it.examples.isNotEmpty() }.sortedBy { it.id }
        val files = withExamples.associate { entry ->
            "$folder/${pascal(entry.id)}Examples.kt" to exampleFile(entry, monarchImports)
        }
        val all = withExamples.joinToString(" +\n        ") { "${pascal(it.id)}Examples" }.ifEmpty { "emptyList()" }
        val index = header("the examples of every inventory file") +
            "package $EXAMPLES_PACKAGE\n\nimport com.rookhq.monarch.testing.InventoryExample\n\n" +
            "/** Every compiled example of every inventory file. */\n" +
            "internal val AllInventoryExamples: List<InventoryExample> =\n    $all\n"
        return files + ("$folder/AllInventoryExamples.kt" to index)
    }

    private fun exampleFile(entry: InventoryEntry, monarchImports: List<String>): String {
        val prefix = pascal(entry.id)
        val imports = (defaultImports + monarchImports + entry.examples.flatMap { it.imports }).distinct().sorted()
        val functions = entry.examples.mapIndexed { index, example ->
            val setup = example.setup?.let { indent(it) + "\n" }.orEmpty()
            "/** inventory/${entry.id}.json, example ${index + 1}: ${example.title} */\n" +
                "@Composable\ninternal fun ${prefix}Example$index() {\n$setup${indent(example.code)}\n}\n"
        }
        val list = entry.examples.mapIndexed { index, example ->
            "    InventoryExample(id = ${literal(entry.id)}, title = ${literal(example.title)}) { ${prefix}Example$index() },"
        }
        return header("inventory/${entry.id}.json") +
            "@file:OptIn(ExperimentalMaterial3Api::class, ExperimentalLayoutApi::class)\n\n" +
            "package $EXAMPLES_PACKAGE\n\n" +
            imports.joinToString("") { "import $it\n" } + "\n" +
            functions.joinToString("\n") + "\n" +
            "internal val ${prefix}Examples: List<InventoryExample> = listOf(\n${list.joinToString("\n")}\n)\n"
    }

    /** The registry that the matrix test reads. */
    fun fixtureRegistry(fixtures: List<FixtureSet>): String {
        val lines = fixtures.joinToString("\n") { "    ${it.qualifiedName}," }
        return header("every `object … : ComponentFixtures` under monarch-compose/src/test") +
            "package com.rookhq.monarch.generated\n\nimport com.rookhq.monarch.testing.ComponentFixtures\n\n" +
            "/** The fixtures of every component, for ComponentMatrixTest. */\n" +
            "internal val AllComponentFixtures: List<ComponentFixtures> = listOf(\n$lines\n)\n"
    }

    /** The families and pages of the sample catalogue. */
    fun catalogueRegistry(pages: List<CataloguePageSource>): String {
        val blocks = pages.groupBy { it.familyPackage }.toSortedMap().map { (family, list) ->
            val items = list.joinToString("\n") { "            ${it.packageName}.${it.objectName}," }
            "    CatalogueFamily(\n        title = ${literal(Families.titleOf(family) ?: family)},\n" +
                "        pages = listOf(\n$items\n        ),\n    ),"
        }
        return header("every `object … : CataloguePage` under sample/…/sections/<family>/") +
            "package com.rookhq.monarch.sample.generated\n\nimport com.rookhq.monarch.sample.CatalogueFamily\n\n" +
            "/** The families of the catalogue and their pages, in alphabetical order. */\n" +
            "internal val CatalogueFamilies: List<CatalogueFamily> = listOf(\n${blocks.joinToString("\n")}\n)\n"
    }

    private fun indent(text: String): String =
        text.lines().joinToString("\n") { if (it.isBlank()) "" else "    $it" }

    private fun literal(text: String): String =
        "\"" + text.replace("\\", "\\\\").replace("\"", "\\\"").replace("$", "\\$") + "\""

    /** Writes [files] under [directory] and removes every other file there. */
    fun sync(directory: File, files: Map<String, String>) {
        directory.walkBottomUp().filter { it.isFile }.forEach { file ->
            if (file.relativeTo(directory).invariantSeparatorsPath !in files) file.delete()
        }
        files.forEach { (path, content) ->
            val target = File(directory, path)
            if (!target.isFile || target.readText() != content) {
                target.parentFile.mkdirs()
                target.writeText(content)
            }
        }
    }
}
